-- Base do EVO MKT (mesmo esquema da versão PHP: um banco existente pode ser reaproveitado).
CREATE TABLE IF NOT EXISTS records(modulo VARCHAR(64) NOT NULL,id VARCHAR(64) NOT NULL,data LONGTEXT NOT NULL,criado_em VARCHAR(40) NOT NULL,atualizado_em VARCHAR(40) NOT NULL,PRIMARY KEY(modulo,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS module_headers(modulo VARCHAR(64) PRIMARY KEY,headers LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS id_counters(modulo VARCHAR(64) PRIMARY KEY,n INTEGER NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS used_ids(id VARCHAR(64) PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS users(codigo VARCHAR(64) PRIMARY KEY,nome VARCHAR(120) NOT NULL,role VARCHAR(20) NOT NULL,label VARCHAR(120) NOT NULL,pass_hash VARCHAR(255) NOT NULL,must_change INTEGER NOT NULL DEFAULT 1,ativo INTEGER NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS portal_users(codigo VARCHAR(64) PRIMARY KEY,nome VARCHAR(120) NOT NULL,perfil VARCHAR(60) NOT NULL,segmentos LONGTEXT NOT NULL,pass_hash VARCHAR(255) NOT NULL,must_change INTEGER NOT NULL DEFAULT 1,ativo INTEGER NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sessions(token_hash VARCHAR(64) PRIMARY KEY,tipo VARCHAR(10) NOT NULL,codigo VARCHAR(64) NOT NULL,expira INTEGER NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS login_attempts(chave VARCHAR(190) NOT NULL,quando INTEGER NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS notices(id VARCHAR(64) PRIMARY KEY,data LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,quando VARCHAR(40) NOT NULL,ator VARCHAR(120) NOT NULL,acao VARCHAR(60) NOT NULL,modulo VARCHAR(40) NOT NULL,registro VARCHAR(64) NOT NULL,ip VARCHAR(64) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
